			       unsigned flags, int delta)
{
	switch (flags & (PARENT1 | PARENT2 | STALE)) {
	case PARENT1:
		state->parent1_count += delta;
		break;

	case PARENT2:
		state->parent2_count += delta;
		break;

	case PARENT1 | PARENT2:
		state->mb_candidate_count += delta;
		break;

	case PARENT1 | PARENT2 | STALE:
